style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com"), domain("create.roblox.com") {
/* SENİN GOTH KARI WALLPAPER – FIXED CENTER COVER */
    body, html, .rbx-body {
        background: url('https://i.ibb.co.com/0jZJ7nK/goth-vampire-wallpaper.jpg') fixed center/cover no-repeat !important;
        background-color: #000000 !important;
    }

    /* TÜM ROBLOX CONTAINER'LARI TRANSPARENT ZORLA – WALLPAPER ÇIKSIN AMK */
    .content, .container-main, .rbx-container, .section, .section-content,
    #header, .rbx-header, .rbx-left-col, .rbx-right-col, #navigation,
    .dark-theme, .light-theme, div[class*="background"], div[class*="container"],
    div[class*="content"], *[class*="bg-"], *[style*="background"],
    .notification-stream-wrap, .game-card-container, .popover, .dropdown-menu {
        background: transparent !important;
        background-color: transparent !important;
        background-image: none !important;
    }

    /* İNATÇI KALANLARI WILDCARD'LA SİK – HEPSİ GİTSİN */
    * { background-image: none !important; background-color: transparent !important; }

    /* YAZILAR OKUNSUN – KORKUNÇ KARANLIK RESİMDE GÖLGE + BEYAZ */
    h1, h2, h3, p, span, a, .text-label, .rbx-text, .gotham-font, .font-header-2 {
        text-shadow: 0 0 10px black, 2px 2px 8px black !important;
        color: #ffffff !important; /* İstemezsen sil */
    }

    /* DARK MODE ZORLA (EN İYİ DURUR BU RESİMDE) + KONTRAST */
    .light-theme { filter: brightness(0.8) contrast(1.3) !important; }
    .dark-theme { filter: brightness(1.1) !important; }
}
